/**
 * Unit tests for FastMath.cosh(double x)
 */
public class FastMath_cosh_TriageGen0Test {

    private static final double DELTA = 1e-14;



    @Test
    public void testCoshZero() {
        // cosh(0) = (exp(0) + exp(0))/2 = 1
        assertEquals(1.0, FastMath.cosh(0.0), DELTA);
        assertEquals(1.0, FastMath.cosh(-0.0), DELTA);
    }














}

