package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for FastMath.cosh(double x)
 */
public class FastMath_cosh_TriageGen0Test {

    private static final double DELTA = 1e-14;













    @Test
    public void testCoshBoundary20() {
        // Testing the boundary of the if(x > 20) condition
        double x = 20.0;
        double expected = (Math.exp(x) + Math.exp(-x)) / 2.0;
        assertEquals(expected, FastMath.cosh(x), DELTA);

        double xNeg = -20.0;
        double expectedNeg = (Math.exp(xNeg) + Math.exp(-xNeg)) / 2.0;
        assertEquals(expectedNeg, FastMath.cosh(xNeg), DELTA);
    }




}

