/**
 * Unit tests for FastMath.cosh(double x)
 */
public class FastMath_cosh_TriageGen0Test {

    private static final double DELTA = 1e-14;

















    @Test
    public void testCoshExtreme() {
        // Test overflow behavior (though the method handles it via the > 20 branch)
        // FastMath.exp(710) is near Double.MAX_VALUE
        double x = 700.0;
        double expected = 0.5 * FastMath.exp(x);
        assertEquals(expected, FastMath.cosh(x), expected * 1e-15);
    }
